//! Read-only resource table string/configuration catalog. Unsupported chunks
//! are reported; compiled resources are never regenerated by Workshop.
use super::binary::*;
use crate::task::Cancellation;
use std::{collections::BTreeMap, io};
#[derive(Default)]
pub struct Resources {
    pub values: BTreeMap<u32, Vec<(String, String)>>,
    pub notes: Vec<String>,
    metadata_bytes: usize,
}
impl Resources {
    pub fn parse(data: &[u8], cancel: &Cancellation) -> io::Result<Self> {
        if data.len() > 32 * 1024 * 1024
            || u16_at(data, 0)? != 2
            || u32_at(data, 4)? as usize != data.len()
        {
            return Err(error("Unsupported resource table"));
        }
        let head = u16_at(data, 2)? as usize;
        if head < 12 || head > data.len() {
            return Err(error("Invalid resource table header"));
        }
        let mut result = Self::default();
        let mut strings = Vec::new();
        let mut p = head;
        while p < data.len() {
            cancel.check()?;
            let (kind, head, size) = chunk(data, p)?;
            let raw = bytes(data, p, size)?;
            match kind {
                1 => strings = super::manifest::pool(raw)?,
                0x200 => result.package(raw, head, &strings, cancel)?,
                _ => result
                    .notes
                    .push(format!("Resource chunk 0x{kind:04x} is not decoded")),
            }
            p += size;
        }
        Ok(result)
    }
    fn package(
        &mut self,
        data: &[u8],
        head: usize,
        strings: &[String],
        cancel: &Cancellation,
    ) -> io::Result<()> {
        if head < 284 {
            return Err(error("Unsupported resource package"));
        }
        let package = u32_at(data, 8)?;
        if package > 255 {
            return Err(error("Invalid resource package ID"));
        }
        let type_offset = if head >= 288 { u32_at(data, 284)? } else { 0 };
        if type_offset > 255 {
            return Err(error("Unsupported resource type offset"));
        }
        let types = super::manifest::pool(pool_chunk(data, u32_at(data, 268)? as usize)?)?;
        let keys = super::manifest::pool(pool_chunk(data, u32_at(data, 276)? as usize)?)?;
        let mut p = head;
        while p < data.len() {
            cancel.check()?;
            let (kind, h, size) = chunk(data, p)?;
            let raw = bytes(data, p, size)?;
            if kind == 0x201 {
                if h < 28 {
                    return Err(error("Invalid resource type header"));
                }
                let id = raw[8] as u32 + type_offset;
                let flags = raw[9];
                let count = u32_at(raw, 12)? as usize;
                let start = u32_at(raw, 16)? as usize;
                if count > 65536 || id == 0 || id > 255 || start < h || start > size {
                    return Err(error("Invalid resource type bounds"));
                }
                let config_size = u32_at(raw, 20)? as usize;
                if config_size < 8 || config_size > h - 20 {
                    return Err(error("Invalid resource configuration"));
                }
                let locale = if config_size >= 12 {
                    let lang = bytes(raw, 28, 2)?;
                    let country = bytes(raw, 30, 2)?;
                    if lang == [0, 0] {
                        "default".into()
                    } else {
                        format!(
                            "{}-{}",
                            String::from_utf8_lossy(lang),
                            String::from_utf8_lossy(country)
                        )
                    }
                } else {
                    "default".into()
                };
                let type_name = types
                    .get(raw[8].saturating_sub(1) as usize)
                    .map(String::as_str)
                    .unwrap_or("?");
                if flags & !3 != 0 {
                    self.notes
                        .push(format!("Unsupported resource type flags: {flags}"));
                    p += size;
                    continue;
                }
                let entries = if flags & 1 != 0 {
                    if !(start - h).is_multiple_of(4) {
                        return Err(error("Invalid sparse resource table"));
                    }
                    if (start - h) / 4 > 100_000 {
                        return Err(error("Sparse resource table exceeds limit"));
                    }
                    (0..(start - h) / 4)
                        .map(|n| {
                            Ok((
                                u16_at(raw, h + n * 4)? as usize,
                                u16_at(raw, h + n * 4 + 2)? as usize * 4,
                            ))
                        })
                        .collect::<io::Result<Vec<_>>>()?
                } else {
                    let width = if flags & 2 != 0 { 2 } else { 4 };
                    bytes(raw, h, count * width)?;
                    if h + count * width > start {
                        return Err(error("Resource offsets overlap entries"));
                    }
                    (0..count)
                        .map(|n| {
                            let offset = if width == 2 {
                                let v = u16_at(raw, h + n * 2)?;
                                if v == u16::MAX {
                                    usize::MAX
                                } else {
                                    v as usize * 4
                                }
                            } else {
                                let v = u32_at(raw, h + n * 4)?;
                                if v == u32::MAX {
                                    usize::MAX
                                } else {
                                    v as usize
                                }
                            };
                            Ok((n, offset))
                        })
                        .collect::<io::Result<Vec<_>>>()?
                };
                for (index, offset) in entries {
                    cancel.check()?;
                    if offset == usize::MAX {
                        continue;
                    }
                    if index > 65535 {
                        return Err(error("Invalid resource entry ID"));
                    }
                    let e = start
                        .checked_add(offset)
                        .ok_or_else(|| error("Resource entry offset overflow"))?;
                    let entry_size = u16_at(raw, e)? as usize;
                    let entry_flags = u16_at(raw, e + 2)?;
                    if entry_size < 8 {
                        return Err(error("Invalid resource entry"));
                    }
                    let key = keys
                        .get(u32_at(raw, e + 4)? as usize)
                        .ok_or_else(|| error("Invalid resource key"))?;
                    let value = if entry_flags & 1 != 0 {
                        "[complex resource]".into()
                    } else {
                        let value = bytes(raw, e + entry_size, 8)?;
                        let id = u32_at(value, 4)?;
                        match value[3] {
                            3 => strings
                                .get(id as usize)
                                .cloned()
                                .ok_or_else(|| error("Invalid resource string"))?,
                            1 => format!("@0x{id:08x}"),
                            0x10 => id.to_string(),
                            0x12 => (id != 0).to_string(),
                            _ => format!("[type 0x{:02x}: 0x{id:x}]", value[3]),
                        }
                    };
                    self.metadata_bytes += value.len() + key.len() + locale.len() + 32;
                    if self.metadata_bytes > 16 * 1024 * 1024 {
                        return Err(error("Decoded resources exceed limit"));
                    }
                    let id = (package << 24) | (id << 16) | index as u32;
                    self.values
                        .entry(id)
                        .or_default()
                        .push((format!("{type_name}/{key} [{locale}]"), value));
                    if self.values.len() > 100_000 {
                        return Err(error("Too many resource entries"));
                    }
                }
            } else if !matches!(kind, 1 | 0x202) {
                self.notes.push(format!(
                    "Package resource chunk 0x{kind:04x} is not decoded"
                ));
            }
            p += size;
        }
        Ok(())
    }
    pub fn rows(&self) -> Vec<String> {
        self.values
            .iter()
            .flat_map(|(id, values)| {
                values
                    .iter()
                    .map(move |(key, value)| format!("@0x{id:08x} {key}: {value}"))
            })
            .chain(self.notes.iter().cloned())
            .collect()
    }
}
fn chunk(data: &[u8], p: usize) -> io::Result<(u16, usize, usize)> {
    let kind = u16_at(data, p)?;
    let head = u16_at(data, p + 2)? as usize;
    let size = u32_at(data, p + 4)? as usize;
    if head < 8 || size < head {
        return Err(error("Invalid resource chunk size"));
    }
    bytes(data, p, size)?;
    Ok((kind, head, size))
}
fn pool_chunk(data: &[u8], p: usize) -> io::Result<&[u8]> {
    let (kind, _, size) = chunk(data, p)?;
    if kind != 1 {
        return Err(error("Missing resource name pool"));
    }
    bytes(data, p, size)
}
